// grid-shelf-view-model is exclusively used for Shorts grids in search results.
// Confirm by checking for the Shorts lockup child before hiding.
const hasShorts = element.querySelector('ytm-shorts-lockup-view-model-v2');
if (!hasShorts) return;
element.style.display = 'none';

// Hide section headers that belong to a Shorts grid shelf
const parent = element.closest('grid-shelf-view-model');
if (!parent) return;
element.style.display = 'none';
